window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[342]={"id":"342","numero":342,"titre":"Malaise · perte de connaissance · crise convulsive","objectifs":[{"id":"342-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un malaise, d’une syncope, d’une lipothymie, des prodromes, d’une crise comitiale et d’un état de mal épileptique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"342-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme physiopathologique principal d’un malaise","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique d’un patient ayant souffert d’un malaise ou d’une perte de connaissance","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":3},{"id":"342-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic des syncopes et lipothymies","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":4},{"id":"342-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic d’une hypotension orthostatique, d’une hypoglycémie","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques d’un événement épileptique et non épileptique (pseudo-crise)","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":7},{"id":"342-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes cardiovasculaires et non cardiovasculaires des syncopes/lipothymies","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"342-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes neurologiques des malaises, des crises épileptiques","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes non cardiaques et non neurologiques de malaises","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"342-10","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la gravité des malaises en fonction de leur cause et la surveillance à entreprendre","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications et connaître les anomalies décisives de l’électrocardiogramme (ECG) en cas de syncope ou lipothymie","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":3},{"id":"342-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications d’un électroencéphalogramme en cas de survenue d’un malaise ou d’une perte de connaissance présumés d’origine épileptique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"342-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens de seconde intention dans les syncopes et lipothymies","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"342-14","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les éléments cliniques et paracliniques justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"342-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les gestes d’urgence à effectuer en présence d’une crise convulsive généralisée","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique d’un malaise","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations et l’organisation du suivi d’un patient vu pour malaise, syncope ou lipothymie de cause rythmique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"342-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations et l’organisation du suivi d’un patient vu pour malaise, syncope ou lipothymie réflexe","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations et l’organisation du suivi d’un patient vu pour malaise, hypotension artérielle orthostatique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et les modalités de prescription d’un traitement anticonvulsivant","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"342-21","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge de la crise comitiale","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-12-item-342-malaises-perte-de-connaissance-crise-comitiale-chez-ladulte","label":"sfcardio.fr"},{"href":"https://www.cen-neurologie.fr/second-cycle/malaise-perte-de-connaissance-crise-comitiale-chez-ladulte","label":"cen-neurologie.fr"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Perte de connaissance transitoire — Évaluation initiale : interrogatoire + témoins, examen physique, PA couché/debout, ECG, glycémie capillaire.","detail":"<h4>Démarche diagnostique face à une PDC — D'après l'algorithme HAS 2008 — évaluation initiale puis orientation étiologique.</h4>","branches":[{"to":"q-syncope","label":"Hypoperfusion cérébrale globale (pâleur, prodromes, reprise rapide)","color":"blue"},{"to":"t-orl","label":"Orienté ORL (vertige, instabilité)","color":"blue"},{"to":"t-autre","label":"Récupération non immédiate, déficit focal, confusion, coma","color":"red"}]},{"id":"q-syncope","kind":"decision","label":"Syncope — Trio interrogatoire + examen + ECG → diagnostic dans ~50 % des cas.","branches":[{"to":"t-certaine","label":"Diagnostic certain d'emblée","color":"green"},{"to":"q-mecanisme","label":"Diagnostic suspecté → explorer le mécanisme","color":"amber"},{"to":"q-inexpliquee","label":"Syncope inexpliquée","color":"blue"}]},{"id":"t-certaine","kind":"terminal","label":"Syncope étiquetée → PEC adaptée","color":"green","detail":"<h4>Clinique</h4><ul><li>Réflexe typique récidivant, identique depuis des années</li><li>ou <span class=\"kw-etio\">HTO</span> documentée avec mesures prises</li></ul><h4>Traitement</h4><ul><li>Mesures hygiéno-diététiques + éducation ; retour à domicile possible si <span class=\"kw-imagerie\">ECG</span> et examen normaux, sans cardiopathie.</li></ul>"},{"id":"q-mecanisme","kind":"decision","label":"Orientation étiologique — Trois grands mécanismes à départager.","branches":[{"to":"t-cardiaque","label":"Contexte cardiaque (effort, palpitations, décubitus, souffle, ECG anormal)","color":"red"},{"to":"t-ortho","label":"Orthostatique (au lever, sujet âgé, iatrogène)","color":"amber"},{"to":"t-reflexe","label":"Réflexe (déclencheur situationnel, prodromes vagaux)","color":"green"}]},{"id":"t-cardiaque","kind":"terminal","label":"Cause cardiaque — La plus grave — risque de mort subite.","color":"red","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ETT</span> + <span class=\"kw-bio\">Holter</span> en 1ʳᵉ ligne</li><li>puis <span class=\"kw-bio\">EEP</span>, puis <span class=\"kw-bio\">MEI</span> si négatif</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Avis cardiologique &lt; 24 h</span> + monitorage <span class=\"kw-imagerie\">ECG</span> scopé.</li></ul>"},{"id":"t-ortho","kind":"terminal","label":"Cause orthostatique","color":"amber","detail":"<h4>Paraclinique</h4><ul><li>Test d'<span class=\"kw-clinique\">hypotension orthostatique</span> répété (le matin ++) ; ± <span class=\"kw-imagerie\">MAPA</span>.</li></ul><h4>Traitement</h4><ul><li>Adapter <span class=\"kw-clinique\">les</span> traitements hypotenseurs</li><li>hydratation, contention veineuse, verticalisation progressive</li></ul>"},{"id":"t-reflexe","kind":"terminal","label":"Cause réflexe — La plus fréquente et la plus bénigne.","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Massage du sinus carotidien</span> si &gt;<span class=\"kw-chiffre\"> 40 ans</span></li><li>test d'inclinaison (tilt-test) en cas de doute</li></ul><h4>Traitement</h4><ul><li>Éducation + réassurance ; traitement spécifique seulement dans <span class=\"kw-clinique\">les</span> formes invalidantes.</li></ul>"},{"id":"q-inexpliquee","kind":"decision","label":"Syncope inexpliquée — Décision selon la fréquence et la sévérité des épisodes.","branches":[{"to":"t-explorations","label":"Récidivante ou sévère","color":"amber"},{"to":"t-arret","label":"Épisode unique sans gravité","color":"green"}]},{"id":"t-explorations","kind":"terminal","label":"Explorations approfondies","color":"amber","detail":"<h4>Paraclinique</h4><ul><li>Massage sino-carotidien + test d'inclinaison</li><li>monitorage prolongé : <span class=\"kw-bio\">MEI</span> (autonomie &gt;<span class=\"kw-chiffre\"> 2 ans</span>)</li></ul>"},{"id":"t-arret","kind":"terminal","label":"Arrêt des explorations","color":"green","detail":"<h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> simple ; reprise du bilan uniquement en cas de récidive.</li></ul>"},{"id":"t-orl","kind":"terminal","label":"Orientation ORL","color":"blue","detail":"<h4>Clinique</h4><ul><li>Pas de vraie PDC par hypoperfusion globale → bilan vestibulaire / ORL orienté.</li></ul>"},{"id":"t-autre","kind":"terminal","label":"Autre trouble de la conscience — Ne pas étiqueter « syncope » par excès.","color":"red","detail":"<h4>Clinique</h4><ul><li>Crise d'<span class=\"kw-def\">épilepsie</span> (morsure latérale, confusion post-critique)</li><li><span class=\"kw-def\">AVC</span> / <span class=\"kw-alerte\">AIT</span> vertébro-basilaire, <span class=\"kw-etio\">HSA</span></li><li><span class=\"kw-etio\">hypoglycémie</span>, intoxication, <span class=\"kw-alerte\">coma</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Avis neurologique ou réanimatoire</span> en <span class=\"kw-alerte\">urgence</span> selon la gravité.</li></ul>"}]},"cards":[{"i":"2ee47be69e34","n":342,"o":"342-10","u":"Identifier une urgence","t":"Connaître la gravité des malaises en fonction de leur cause et la surveillance à entreprendre","q":"Quels sont les éléments cliniques pouvant orienter vers un malaise grave ?","a":"<p>Bien que le contenu source soit peu détaillé, les éléments cliniques pouvant orienter vers un malaise grave incluent :</p><ul><li>Un <strong>terrain à risque</strong> (cardiaque connu, âge avancé, polypathologies).</li><li>Un malaise survenu <strong>à l'effort</strong> ou en <strong>décubitus</strong>.</li><li>La présence de <strong>douleurs thoraciques</strong>, palpitations, dyspnée.</li><li>La présence de <strong>signes neurologiques focaux</strong> ou d'un déficit persistant.</li><li>Une <strong>amnésie post-épileptique</strong> prolongée ou une répétition des crises.</li><li>Des paramètres vitaux <strong>instables</strong> (hypotension artérielle, bradycardie ou tachycardie extrêmes, troubles de la conscience prolongés).</li></ul>"},{"i":"4b25bd121fd2","n":342,"o":"342-10","u":"Identifier une urgence","t":"Connaître la gravité des malaises en fonction de leur cause et la surveillance à entreprendre","q":"Comment évalue-t-on la gravité d'un malaise en fonction de sa cause ?","a":"<p>Bien que le contenu ne donne pas d'exemples précis, l'évaluation de la gravité d'un malaise repose généralement sur :</p><ul><li>La <strong>cause sous-jacente</strong> (cardiaque, neurologique, métabolique, etc.).</li><li>La <strong>profondeur de l'altération de la conscience</strong>.</li><li>La <strong>présence de signes d'accompagnement</strong> (douleur thoracique, déficit neurologique, convulsion).</li><li>Le <strong>terrain du patient</strong> (âge, comorbidités).</li></ul>"},{"i":"e48ff7ecbff9","n":342,"o":"342-10","u":"Identifier une urgence","t":"Connaître la gravité des malaises en fonction de leur cause et la surveillance à entreprendre","q":"Quels sont les principes généraux de la surveillance à entreprendre après un malaise ?","a":"<p>La surveillance doit être adaptée à la cause suspectée et comprend généralement :</p><ul><li>La surveillance des <strong>fonctions vitales</strong> : conscience (score de Glasgow), pression artérielle, fréquence cardiaque, fréquence respiratoire, saturation en oxygène, température.</li><li>La surveillance de l'<strong>état neurologique</strong> (si cause neurologique suspectée).</li><li>La recherche de <strong>signes d'aggravation</strong> ou de récidive.</li><li>La surveillance des <strong>paramètres spécifiques</strong> liés à la cause (glycémie, ECG, etc.).</li></ul>"},{"i":"2249b395f991","n":342,"o":"342-11","u":"Examens complémentaires","t":"Connaître les indications et connaître les anomalies décisives de l’électrocardiogramme (ECG) en cas de syncope ou lipothymie","q":"Dans le contexte d'une syncope ou d'une lipothymie, quelle est l'indication principale d'un électrocardiogramme (ECG) ?","a":"<p>L'ECG est indiqué de manière <strong>systématique</strong> devant toute syncope ou lipothymie.</p>"},{"i":"513e5e839cbc","n":342,"o":"342-11","u":"Examens complémentaires","t":"Connaître les indications et connaître les anomalies décisives de l’électrocardiogramme (ECG) en cas de syncope ou lipothymie","q":"Quelles anomalies électrocardiographiques peuvent être décisives pour le diagnostic étiologique d'une syncope ou d'une lipothymie d'origine cardiaque ?","a":"<ul><li><strong>Bradycardie</strong> ou <strong>tachycardie</strong> (ventriculaire ou supraventriculaire).</li><li>Anomalies de la repolarisation (ondes <strong>T négatives</strong> ou <strong>pointues</strong>, <strong>sous-décalage</strong> ou <strong>sus-décalage du segment ST</strong>).</li><li>Allongement ou raccourcissement de l'intervalle <strong>QT</strong>.</li><li>Blocs de conduction (<strong>bloc auriculo-ventriculaire</strong> du 2<sup>e</sup> ou 3<sup>e</sup> degré, <strong>bloc de branche</strong>).</li><li>Signes d'hypertrophie ventriculaire.</li><li>Onde <strong>epsilon</strong> dans la dysplasie arythmogène du ventricule droit.</li><li>Aspect type <strong>Brugada</strong>.</li><li>Signes d'<strong>ischémie myocardique</strong> ou d'<strong>infarctus</strong>.</li></ul>"},{"i":"a42da77e420c","n":342,"o":"342-11","u":"Examens complémentaires","t":"Connaître les indications et connaître les anomalies décisives de l’électrocardiogramme (ECG) en cas de syncope ou lipothymie","q":"Quel type d'anomalie ECG est particulièrement important à rechercher face à une syncope inexpliquée chez un sujet jeune, potentiellement d'origine génétique ?","a":"<p>Il est crucial de rechercher des anomalies comme l'<strong>allongement de l'intervalle QT</strong> (syndrome du QT long congénital) ou un aspect de type <strong>Brugada</strong>, souvent associés à des syncopes graves et des risques de mort subite chez le sujet jeune.</p>"},{"i":"1f2e053e23cd","n":342,"o":"342-14","u":"Identifier une urgence","t":"Identifier les éléments cliniques et paracliniques justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence","q":"Quand faut-il faire un avis réanimatoire en urgence face à un patient ayant présenté un malaise, une perte de connaissance ou une crise convulsive ?","a":"<p>Un avis réanimatoire en urgence est nécessaire en présence de :</p><ul><li>Une <strong>instabilité hémodynamique</strong> (choc, hypotension sévère).</li><li>Des <strong>troubles ventilatoires</strong> (bradypnée, hypoventilation, désaturation).</li><li>Un <strong>trouble de conscience profond</strong> (coma Glasgow ≤ 8) ou d'aggravation rapide.</li><li>Un <strong>état de mal épileptique réfractaire</strong>.</li><li>Une <strong>hypoglycémie</strong> ou autre <strong>trouble métabolique majeur</strong> non corrigé.</li><li>Des signes de <strong>défaillance d'organe</strong> (rénale, hépatique aiguë).</li></ul>"},{"i":"28a49410ccf6","n":342,"o":"342-14","u":"Identifier une urgence","t":"Identifier les éléments cliniques et paracliniques justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence","q":"Quels éléments cliniques et paracliniques, suite à un malaise, une perte de connaissance ou une crise convulsive, justifient un avis neurologique en urgence ?","a":"<p>Les éléments justifiant un avis neurologique urgent sont :</p><ul><li>Des <strong>signes de localisation neurologique</strong> persistants (déficit moteur, sensitif, troubles du langage, paralysie faciale).</li><li>Une <strong>crise convulsive prolongée</strong> (état de mal épileptique) ou des <strong>crises répétées</strong>.</li><li>Des <strong>céphalées intenses</strong> ou des <strong>signes méningés</strong> associés.</li><li>Des troubles de conscience persistants ou s'aggravant.</li><li>Un fond d'œil révélant des signes d'<strong>hypertension intracrânienne</strong> (œdème papillaire).</li><li>Une suspicion de <strong>lésion cérébrale aiguë</strong> (AVC, hémorragie).</li></ul>"},{"i":"3e3717402c5d","n":342,"o":"342-14","u":"Identifier une urgence","t":"Identifier les éléments cliniques et paracliniques justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence","q":"Dans le cadre d'un malaise, d'une perte de connaissance ou d'une crise convulsive, quels signes cliniques à l'examen physique orientent vers un avis cardiologique en urgence ?","a":"<p>Les signes cliniques orientant vers un avis cardiologique urgent sont :</p><ul><li>Une <strong>bradycardie</strong> ou une <strong>tachycardie</strong> significative.</li><li>Des <strong>souffles cardiaques</strong> ou des signes d'insuffisance cardiaque (œdèmes, crépitants).</li><li>Une <strong>hypotension artérielle</strong> inexpliquée.</li><li>Des antécédents de <strong>pathologie cardiaque structurelle</strong> (cardiomyopathie, valvulopathie) ou de <strong>troubles du rythme</strong>.</li><li>Un <strong>ECG anormal</strong> (troubles de conduction, QT long, ondes Q pathologiques).</li></ul>"},{"i":"63d390fe493c","n":342,"o":"342-14","u":"Identifier une urgence","t":"Identifier les éléments cliniques et paracliniques justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence","q":"Compte tenu de l'objectif (Identifier les éléments justifiant d’un avis cardiologique, neurologique ou réanimatoire en urgence en cas de malaise, perte de connaissance ou crise convulsive), quelles catégories d'informations cliniques sont primordiales à recueillir dès l'anamnèse ?","a":"<p>Il est primordial de recueillir l'ensemble des informations concernant :</p><ul><li>Les <strong>circonstances</strong> de survenue de l'événement (activité, position, facteurs déclenchants).</li><li>La <strong>description</strong> précise de l'événement (déroulement, durée, signes associés, récupération).</li><li>Les <strong>antécédents</strong> personnels et familiaux (cardiaques, neurologiques, épilepsie, mort subite).</li><li>La <strong>prise médicamenteuse</strong> (notamment cardiotoxiques ou psychotropes).</li></ul>"},{"i":"7509bb302e94","n":342,"o":"342-16","u":"Prise en charge","t":"Connaître le traitement symptomatique d’un malaise","q":"Quels sont les éléments clés à renseigner rapidement lors de la prise en charge d'un malaise pour orienter le diagnostic et le traitement symptomatique ?","a":"<ul><li>Le <strong>contexte de survenue</strong> du malaise (activité, environnement, prodromes).</li><li>La <strong>description des symptômes</strong> associés (douleur thoracique, dyspnée, palpitations, nausées, vertiges, sudation…).</li><li>Les <strong>antécédents</strong> médicaux du patient, ses traitements.</li><li>La présence ou non d'une <strong>perte de connaissance</strong> et sa durée.</li><li>L'évaluation des <strong>fonctions vitales</strong> (conscience, ventilation, TA, pouls, température, glycémie capillaire).</li></ul>"},{"i":"992bca6e6656","n":342,"o":"342-16","u":"Prise en charge","t":"Connaître le traitement symptomatique d’un malaise","q":"Quels sont les premiers gestes à réaliser lors de la prise en charge symptomatique d'un malaise, hors contexte traumatique ?","a":"<ul><li>Mise en position de sécurité (en général, position latérale de sécurité si perte de connaissance avec ventilation spontanée efficace, ou position allongée).</li><li>Libération et maintien des <strong>voies aériennes supérieures</strong> (VAS).</li><li>Évaluation rapide de la conscience, de la ventilation, et de la circulation (le fameux « A-B-C »).</li><li>Protection de la personne et de son environnement (ex: en cas de chute ou de convulsion).</li><li>Alerte des secours médicalisés si besoin.</li></ul>"},{"i":"a18e7e76aa8c","n":342,"o":"342-16","u":"Prise en charge","t":"Connaître le traitement symptomatique d’un malaise","q":"Comment définir simplement un malaise dans le contexte d'une prise en charge médicale initiale ?","a":"<p>Un malaise est une <strong>sensation d'inconfort</strong> ou de <strong>mal-être physique et/ou psychique</strong> d'apparition généralement <strong>brutale</strong>, pouvant être accompagné de signes physiques variés et dont les causes sont très nombreuses.</p>"},{"i":"becfc913d656","n":342,"o":"342-20","u":"Prise en charge","t":"Connaître les indications et les modalités de prescription d’un traitement anticonvulsivant","q":"Quelles sont les indications d'un traitement anti-convulsivant, selon les recommandations actuelles ?","a":"<p>Bien que l'objectif EDN 342 mentionne les indications de prescription, le contenu source fourni pour cet objectif indique qu'il est \"à compléter\".</p><p>Par conséquent, sans information spécifique sur les indications dans le contenu fourni, il n'est pas possible de générer une réponse précise et complète à cette question dans le cadre des règles établies.</p>"},{"i":"cab4822dea08","n":342,"o":"342-20","u":"Prise en charge","t":"Connaître les indications et les modalités de prescription d’un traitement anticonvulsivant","q":"Quelles sont les modalités de prescription d'un traitement anti-convulsivant face à une crise convulsive, selon les recommandations actuelles ?","a":"<p>Bien que l'objectif EDN 342 mentionne les modalités de prescription, le contenu source fourni pour cet objectif indique qu'il est \"à compléter\".</p><p>Par conséquent, sans information spécifique sur les modalités de prescription dans le contenu fourni, il n'est pas possible de générer une réponse précise et complète à cette question dans le cadre des règles établies.</p>"},{"i":"24040649db82","n":342,"o":"342-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la crise comitiale","q":"Comment définir une crise comitiale ?","a":"<p>Une crise comitiale est une <strong>manifestation clinique transitoire</strong> résultant d'une <strong>activité neuronale excessive et hypersynchrone</strong> au sein du cerveau.</p>"},{"i":"26c61e244d60","n":342,"o":"342-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la crise comitiale","q":"Quand faut-il appeler les secours médicaux d'urgence (15) pour une crise comitiale ?","a":"<ul><li>Si la crise dure <strong>plus de 5 minutes</strong>.</li><li>En cas de <strong>crises répétées sans récupération</strong> complète de la conscience entre chaque crise (état de mal épileptique).</li><li>Si le patient se blesse gravement pendant la crise.</li><li>S'il s'agit d'une <strong>première crise</strong>.</li><li>Si le patient présente des <strong>troubles persistants</strong> après la crise (confusion prolongée, paralysie post-critique).</li><li>En cas de crise chez un patient <strong>enceinte</strong>.</li></ul>"},{"i":"38b0fffb227f","n":342,"o":"342-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la crise comitiale","q":"Comment se fait la surveillance post-critique immédiate après une crise comitiale ?","a":"<p>La surveillance post-critique immédiate inclut l'évaluation de la <strong>conscience</strong> (score de Glasgow), de la <strong>respiration</strong> et de la <strong>circulation</strong>. Il faut rechercher des <strong>signes de traumatisme</strong> et installer le patient en <strong>position latérale de sécurité</strong> tant qu'il n'a pas récupéré complètement sa conscience.</p>"},{"i":"7b342ad4d3b7","n":342,"o":"342-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la crise comitiale","q":"Quel est le premier objectif de la prise en charge initiale d'une crise comitiale ?","a":"<p>Le premier objectif est d'assurer la <strong>sécurité du patient</strong> et de prévenir les blessures potentiellement liées à la crise. Cela inclut de le mettre en position latérale de sécurité si possible, de desserrer ses vêtements et d'éloigner les objets dangereux.</p>"},{"i":"abe7658ad272","n":342,"o":"342-21","u":"Prise en charge","t":"Connaître les principes de la prise en charge de la crise comitiale","q":"Quels sont les gestes à éviter absolument lors de la prise en charge d'une crise comitiale ?","a":"<p>Il faut éviter de <strong>tenter d'immobiliser le patient</strong>, d'<strong>introduire des objets dans la bouche</strong> (risque de blessure pour le patient ou le soignant) ou d'<strong>administrer des médicaments</strong> par voie orale pendant la crise. Il ne faut pas non plus tenter de réanimer un patient qui respire spontanément.</p>"},{"i":"3469bd7df4c1","n":342,"o":"342-3","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique d’un patient ayant souffert d’un malaise ou d’une perte de connaissance","q":"Quels sont les éléments clés de l'examen clinique à rechercher face à un patient ayant présenté un malaise ou une perte de connaissance ?","a":"<p>L'examen clinique doit être systématisé et rechercher :</p><ul><li>Les <strong>constantes vitales</strong> (tension artérielle, fréquence cardiaque, fréquence respiratoire, température, saturation en O2, glycémie capillaire).</li><li>Un examen <strong>neurologique complet</strong> (recherche de séquelles, signes focaux, confusion, examen des paires crâniennes, ROT, sensibilité).</li><li>Un examen <strong>cardiovasculaire</strong> (auscultation cardiaque et pulmonaire, palpation des pouls périphériques, recherche d'une hypotension orthostatique).</li><li>Un examen <strong>général</strong> à la recherche de signes évoquant une étiologie (traumatismes, pâleur, cyanose, sueurs, morsure de langue latérale).</li></ul>"},{"i":"4da04b27a95a","n":342,"o":"342-3","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique d’un patient ayant souffert d’un malaise ou d’une perte de connaissance","q":"A quoi servent les informations recueillies lors de l'interrogatoire et de l'examen clinique initial d'un patient ayant eu un malaise ou une perte de connaissance ?","a":"<p>Ces informations permettent d'<strong>orienter le diagnostic étiologique</strong> (cardiaque, neurologique, métabolique, vasovagal, etc.), d'<strong>évaluer la gravité</strong> de l'épisode, et de <strong>guider les examens complémentaires</strong> à réaliser en urgence ou en différé, tout en identifiant les situations nécessitant une prise en charge immédiate.</p>"},{"i":"c2129174a7b7","n":342,"o":"342-3","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique d’un patient ayant souffert d’un malaise ou d’une perte de connaissance","q":"Quels sont les items essentiels de l'interrogatoire à recueillir face à un patient ayant présenté un malaise ou une perte de connaissance ?","a":"<p>L'interrogatoire doit préciser :</p><ul><li>Les <strong>circonstances</strong> de survenue (facteurs déclenchants, position).</li><li>La <strong>description de l'épisode</strong> par le patient ou les témoins (début brutal/progressif, durée, mouvements anormaux, pâleur, sueurs, cyanose, morsure de langue, incontinence urinaire, confusion post-critique).</li><li>Les <strong>symptômes associés</strong> avant, pendant, et après l'épisode (prodromes, douleurs thoraciques, palpitations, dyspnée, signes neurologiques focaux).</li><li>Les <strong>antécédents médicaux</strong> (cardiaques, neurologiques, diabète, épilepsie), chirurgicaux, et traitements en cours (avec posologie et observance).</li><li>Les <strong>facteurs de risque cardiovasculaires</strong> (tabac, HTA, dyslipidémie, diabète, surpoids, sédentarité).</li><li>La recherche d'une <strong>grossesse</strong> chez la femme en âge de procréer.</li></ul>"},{"i":"21fbfca51180","n":342,"o":"342-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic des syncopes et lipothymies","q":"Quels sont les éléments clés de l'interrogatoire orientant vers une syncope d'origine réflexe (vaso-vagale ou situationnelle) ?","a":"<p>L'interrogatoire doit rechercher :</p><ul><li>Des <strong>facteurs déclenchants</strong> (douleur, émotion, déshydratation, station debout prolongée, miction, défécation, toux).</li><li>Des <strong>prodromes</strong> (nausées, sueurs, pâleur, malaise général, sensation de chaleur).</li><li>Une <strong>récupération rapide et sans confusion</strong>.</li></ul>"},{"i":"5a34855db974","n":342,"o":"342-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic des syncopes et lipothymies","q":"Quelles sont les caractéristiques cliniques orientant vers une syncope de cause cardiaque ?","a":"<p>Une syncope cardiaque est suspectée en cas de :</p><ul><li><strong>Survenue à l'effort</strong> ou en décubitus.</li><li><strong>Absence de prodromes</strong> ou prodromes très brefs.</li><li>Antécédents de <strong>maladie cardiaque connue</strong> (cardiopathie ischémique, valvulaire, troubles du rythme).</li><li>Palpitations, douleur thoracique associées.</li><li>Contexte familial de mort subite.</li></ul>"},{"i":"913e08fbe005","n":342,"o":"342-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic des syncopes et lipothymies","q":"Comment différencier cliniquement une syncope d'une crise convulsive ?","a":"<p>Une <strong>syncope</strong> est une perte de connaissance brève (< 1 minute), de survenue brutale et récupération rapide et complète. Elle est due à une hypoperfusion cérébrale globale transitoire. La <strong>crise convulsive</strong> est caractérisée par des mouvements anormaux stéréotypés, souvent tonico-cloniques, une durée plus longue (plusieurs minutes) et une phase post-critique avec confusion mentale et fatigue.</p>"},{"i":"fd817439d962","n":342,"o":"342-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic des syncopes et lipothymies","q":"Quelle est la définition d'une lipothymie et sa différence avec une syncope ?","a":"<p>La <strong>lipothymie</strong> est une sensation de malaise imminent, avec perte de tonus postural, mais <strong>sans perte de connaissance complète</strong>. Elle partage les mêmes mécanismes physiopathologiques que la syncope (hypoperfusion cérébrale), mais le processus n'est pas allé jusqu'à la perte de conscience totale. On parle souvent de \"quasi-syncope\".</p>"},{"i":"09eee3b996d6","n":342,"o":"342-5","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hypotension orthostatique, d’une hypoglycémie","q":"Quel est le critère diagnostique biologique d'une hypoglycémie ?","a":"<p>Le diagnostic d'hypoglycémie est confirmé biologiquement par une <strong>glycémie plasmatique inférieure à 0,60 g/L (3,3 mmol/L)</strong>.</p>"},{"i":"48e37cae6f34","n":342,"o":"342-5","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hypotension orthostatique, d’une hypoglycémie","q":"Quels sont les signes cliniques évoquant une crise d'hypoglycémie ?","a":"<ul><li><strong>Signes neurovégétatifs adrénergiques</strong> : sueurs, tremblements, palpitations, tachycardie, anxiété, faim intense.</li><li><strong>Signes neuroglycopéniques</strong> (témoignant du manque de glucose cérébral) : troubles du comportement, confusion mentale, difficultés de concentration, troubles visuels (diplopie), céphalées, asthénie, somnolence, voire convulsions ou coma.</li></ul>"},{"i":"62a3ebcc628a","n":342,"o":"342-5","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hypotension orthostatique, d’une hypoglycémie","q":"Quelle est la définition de l'hypotension orthostatique ?","a":"<p>L'hypotension orthostatique se définit par une <strong>chute de la pression artérielle systolique d'au moins 20 mmHg</strong> ou de la <strong>pression artérielle diastolique d'au moins 10 mmHg</strong> dans les <strong>trois minutes</strong> suivant le passage en position debout ou en position tête haute sur table basculante.</p>"},{"i":"0e4693abfac8","n":342,"o":"342-6","u":"Diagnostic positif","t":"Connaître les caractéristiques d’un événement épileptique et non épileptique (pseudo-crise)","q":"Quels diagnostics différentiels majeurs faut-il évoquer face à une suspicion de crise épileptique ?","a":"<p>Les principaux diagnostics différentiels à évoquer sont :</p><ul><li>Les <strong>malaises vagaux</strong> (lipothymie, syncope vasovagale)</li><li>Les <strong>synocpes cardiaques</strong> (arythmie, sténose aortique)</li><li>Les <strong>hypoglycémies</strong></li><li>Les <strong>crises d'anxiété ou de panique</strong>, les <strong>pseudo-crises</strong> (crises non épileptiques psychogènes)</li><li>Les accidents ischémiques transitoires (AIT) parfois.</li></ul>"},{"i":"3b6ead9709f3","n":342,"o":"342-6","u":"Diagnostic positif","t":"Connaître les caractéristiques d’un événement épileptique et non épileptique (pseudo-crise)","q":"Quelle est la principale caractéristique d'un événement épileptique au niveau physiopathologique ?","a":"<p>Un événement épileptique est la conséquence d'une <strong>décharge neuronale excessive et hypersynchrone</strong> au sein du cortex cérébral.</p>"},{"i":"b94f40963268","n":342,"o":"342-6","u":"Diagnostic positif","t":"Connaître les caractéristiques d’un événement épileptique et non épileptique (pseudo-crise)","q":"Comment différencier une crise épileptique d'une pseudo-crise (crise non épileptique psychogène) sur un plan clinique ?","a":"<p>La distinction est souvent difficile, mais certains éléments cliniques peuvent orienter :</p><ul><li>Lors d'une <strong>crise épileptique</strong> : les mouvements sont souvent <strong>stéréotypés</strong>, l'ouverture des yeux est rare ou fixée, il y a fréquemment une <strong>morsure latérale de langue</strong>, et une <strong>confusion post-critique</strong> est quasi constante.</li><li>Lors d'une <strong>pseudo-crise</strong> : les mouvements sont souvent <strong>variés et non stéréotypés</strong>, avec une réactivité possible à l'environnement, une <strong>ouverture des yeux fréquente</strong>, des pleurs ou cris, une <strong>morsure de la pointe de la langue</strong> et l'absence de confusion post-critique typique. La durée est souvent <strong>plus longue</strong> et l'installation est <strong>plus progressive</strong>.</li></ul>"},{"i":"e65fc46bbe89","n":342,"o":"342-7","u":"Étiologies","t":"Connaître les causes cardiovasculaires et non cardiovasculaires des syncopes/lipothymies","q":"Quelles sont les principales causes cardiovasculaires d'une syncope ?","a":"<ul><li><strong>Causes rythmiques (arythmies)</strong> : Tachycardies (ventriculaires, supraventriculaires), Bradycardies (blocs auriculo-ventriculaires, dysfonction sinusale).</li><li><strong>Causes hémodynamiques/structurelles</strong> : Obstruction à l'éjection ventriculaire gauche (sténose aortique, cardiomyopathie hypertrophique obstructive, myxome auriculaire), Hypertension artérielle pulmonaire sévère.</li><li><strong>Dysfonction myocardique</strong> : Infarctus du myocarde, Cardiomyopathies dilatées.</li><li><strong>Pathologies vasculaires</strong> : Dissection aortique.</li></ul>"},{"i":"ed6bb5532115","n":342,"o":"342-7","u":"Étiologies","t":"Connaître les causes cardiovasculaires et non cardiovasculaires des syncopes/lipothymies","q":"Quelles sont les principales causes non cardiovasculaires d'une syncope ou lipothymie ?","a":"<ul><li><strong>Syncope vaso-vagale</strong> (ou neuro-médiatisée) : la plus fréquente, due à une réponse réflexe inappropriée (peur, douleur, station debout prolongée).</li><li><strong>Hypotension orthostatique</strong> : due à une déplétion volémique (déshydratation, hémorragie), médicaments (antihypertenseurs, diurétiques), ou dysautonomie (Parkinson, neuropathies).</li><li><strong>Causes neurologiques</strong> : Accidents Ischémiques Transitoires (AIT) du système vertebro-basilaire, insuffisance vertébro-basilaire, crise convulsive atypique.</li><li><strong>Causes métaboliques</strong> : Hypoglycémie, Hypoxie, hyperventilation.</li><li><strong>Causes médicamenteuses</strong> : médicaments hypotonisants, bradycardisants.</li></ul>"},{"i":"f8b4a19ab17c","n":342,"o":"342-7","u":"Étiologies","t":"Connaître les causes cardiovasculaires et non cardiovasculaires des syncopes/lipothymies","q":"Comment différencier une syncope d'une lipothymie en se basant sur la perte de connaissance ?","a":"<p>La <strong>syncope</strong> se caractérise par une <strong>perte de connaissance brutale et complète</strong>, de durée brève, avec récupération spontanée et rapide. La <strong>lipothymie</strong> est un état pré-syncopal, sans perte de connaissance complète, où le patient ressent des <strong>troubles prémonitoires</strong> (vertiges, faiblesse, sueurs) sans aller jusqu'à l'inconscience.</p>"},{"i":"78754c4c897b","n":342,"o":"342-8","u":"Étiologies","t":"Connaître les causes neurologiques des malaises, des crises épileptiques","q":"Quelles sont les causes neurologiques de crises convulsives ?","a":"<p>Les causes neurologiques de crises convulsives incluent :</p><ul><li>L'<strong>épilepsie</strong> (idiopathique, cryptogénique ou symptomatique).</li><li>Les <strong>tumeurs cérébrales</strong> (primitives ou secondaires).</li><li>Les <strong>malformations vasculaires cérébrales</strong> (comme les anévrismes rompus, les MAV).</li><li>Les <strong>AVC ischémiques ou hémorragiques</strong>.</li><li>Les <strong>traumatismes crâniens</strong>, récents ou anciens (cicatrice corticale).</li><li>Les <strong>infections du système nerveux central</strong> (méningites, encéphalites, abcès cérébraux).</li><li>Les <strong>maladies neurodégénératives</strong> (ex : maladie d'Alzheimer à un stade avancé).</li><li>Les <strong>causes métaboliques</strong> (hypoglycémie sévère, hyponatrémie, hypocalcémie) peuvent entraîner des crises, mais elles sont souvent extra-neurologiques primairement. Cependant, leur retentissement est cérébral.</li><li>Les <strong>toxiques</strong> (alcool, drogues, certains médicaments) peuvent déclencher des crises par un effet direct sur le cerveau ou par un sevrage.</li></ul>"},{"i":"7cefe714c2f1","n":342,"o":"342-8","u":"Étiologies","t":"Connaître les causes neurologiques des malaises, des crises épileptiques","q":"Quelles sont les principales étiologies neurologiques à évoquer face à un malaise ou une perte de connaissance inexpliquée ?","a":"<p>Devant un malaise ou une perte de connaissance d'origine neurologique suspectée, il faut considérer :</p><ul><li>Les <strong>crises d'épilepsie</strong> (avec ou sans convulsions).</li><li>Les <strong>accidents ischémiques transitoires</strong> (AIT), notamment ceux qui impliquent la circulation postérieure.</li><li>Les <strong>syncopes réflexes</strong> (vasovagales, sino-carotidiennes) ou <strong>orthostatiques</strong>, bien qu'elles soient souvent d'origine cardiovasculaire, peuvent parfois être déclenchées par des pathologies neurologiques sous-jacentes.</li><li>Les <strong>migraines avec aura</strong>, particulièrement les formes complexes (rares, aura prolongée, déficits transitoires).</li><li>L'<strong>hydrocéphalie à pression normale</strong> (syndrome d'Adams et Hakim), pouvant causer des malaises ou des chutes.</li></ul>"},{"i":"9257eb91b47b","n":342,"o":"342-8","u":"Étiologies","t":"Connaître les causes neurologiques des malaises, des crises épileptiques","q":"Quelle est la principale distinction clinique neurologique entre une syncope et une crise convulsive généralisée ?","a":"<p>La distinction principale repose sur :</p><ul><li>La <strong>syncope</strong> est une perte de connaissance généralement brève (< 1-2 min), précédée souvent de lipothymie (sueurs, pâleur, nausées) et suivie d'une récupération rapide et complète sans confusion post-critique. Les mouvements sont souvent brefs, peu organisés (myoclonies frustes).</li><li>La <strong>crise convulsive généralisée</strong> (tonico-clonique) est une perte de connaissance souvent plus brutale et prolongée. Elle est caractérisée par des mouvements toniques puis cloniques généralisés. Elle est suivie d'une <strong>phase post-critique</strong> plus longue, avec confusion, désorientation, asthénie et parfois des traumatismes (morsure de langue, incontinence).</li></ul>"},{"i":"11ad9a49734c","n":342,"o":"342-9","u":"Étiologies","t":"Connaître les causes non cardiaques et non neurologiques de malaises","q":"Quelles sont les causes médicamenteuses principales de malaise non cardiaque et non neurologique ?","a":"<p>Les causes médicamenteuses fréquentes de malaise incluent les traitements qui induisent :</p><ul><li>Une <strong>vasodilatation</strong> ou une <strong>hypotension</strong> (anti-hypertenseurs, diurétiques, dérivés nitrés).</li><li>Une <strong>hypoglycémie</strong> (insuline, sulfamides hypoglycémiants).</li><li>Une <strong>sédation excessive</strong> ou une altération de l'état de conscience (psychotropes, opioïdes).</li></ul>"},{"i":"ba33d012c334","n":342,"o":"342-9","u":"Étiologies","t":"Connaître les causes non cardiaques et non neurologiques de malaises","q":"Quelles sont les caractéristiques cliniques d'un malaise vasovagal typique ?","a":"<p>Un malaise vasovagal typique se caractérise souvent par :</p><ul><li>Des <strong>prodromes</strong> (nausées, sueurs, pâleur, sensation de chaleur, bourdonnements d'oreille).</li><li>Un déclenchement par une <strong>émotion forte</strong>, une <strong>douleur intense</strong>, une station debout prolongée.</li><li>Une <strong>récupération rapide et complète</strong> après la chute ou la position allongée.</li></ul>"},{"i":"c872555a5dab","n":342,"o":"342-9","u":"Étiologies","t":"Connaître les causes non cardiaques et non neurologiques de malaises","q":"Quels sont les principaux diagnostics métaboliques à évoquer devant un malaise non cardiaque et non neurologique ?","a":"<p>Devant un malaise non cardiaque et non neurologique, les diagnostics métaboliques à évoquer sont principalement :</p><ul><li>L'<strong>hypoglycémie</strong> (la plus fréquente).</li><li>L'<strong>hyponatrémie</strong> sévère.</li><li>Les troubles de l'équilibre acido-basique sévères.</li></ul>"},{"i":"f087d30ae261","n":342,"o":"342-9","u":"Étiologies","t":"Connaître les causes non cardiaques et non neurologiques de malaises","q":"Quels sont les mécanismes physiopathologiques principaux des causes non cardiaques et non neurologiques de malaise ?","a":"<p>Les malaises non cardiaques et non neurologiques sont principalement causés par :</p><ul><li>Une <strong>hypotension orthostatique</strong> (neurogène ou médicamenteuse).</li><li>Des <strong>dysfonctionnements métaboliques</strong> (hypoglycémie, hyponatrémie sévère).</li><li>Des <strong>situations vasovagales</strong> marquées (douleur intense, émotion forte).</li><li>Des <strong>états d'hypovolémie</strong> (déshydratation aiguë, hémorragie).</li></ul>"}]};